// Fixture dependency for the CLI round-trip test. readData() is the "legitimate" use that
// observe should record into the policy; readOther() is the "new, unexpected" use that a
// policy generated from main.js must deny in enforce mode.
const fs = require("fs");
const path = require("path");

exports.readData = () => fs.readFileSync(path.join(__dirname, "data.txt"), "utf8");
exports.readOther = () => fs.readFileSync(path.join(__dirname, "other.txt"), "utf8");

// Native-addon load (#49). `build/Release/<name>.node` is node-gyp's canonical output path,
// so this is the shape a real native package has. The file is a placeholder — see it — and
// the gate decides before dlopen reaches it either way.
exports.loadAddon = () => require(path.join(__dirname, "build", "Release", "trace-dep.node"));

// --- IPC (#72) and net host globs (#83) round-trips -------------------------------------
//
// Both helpers resolve with a STRING the test can assert on: "CapabilityError" means capwall's
// guard denied the connect before any socket opened, anything else means it let the call
// through. Neither depends on the connection actually succeeding, which is what keeps the
// tests deterministic — capwall decides before the OS is involved.

/** Connect to a unix-domain socket / named pipe by path. */
exports.connectIpc = (sockPath) =>
  new Promise((resolve) => {
    const net = require("net");
    let sock;
    try {
      sock = net.connect(sockPath);
    } catch (err) {
      return resolve(err.name);
    }
    const done = (outcome) => () => {
      sock.destroy();
      resolve(outcome);
    };
    sock.on("connect", done("connected"));
    sock.on("error", done("connect-error"));
  });

/** Connect to a TCP host:port. The host is not expected to resolve. */
exports.connectHost = (host, port) =>
  new Promise((resolve) => {
    const net = require("net");
    let sock;
    try {
      sock = net.connect({ host, port });
    } catch (err) {
      return resolve(err.name);
    }
    const done = () => {
      sock.destroy();
      resolve("allowed-through");
    };
    sock.on("connect", done);
    sock.on("error", done);
  });

// --- package identity (#92 / #93) -----------------------------------------------------------

// A genuinely nested install. Its principal is the install chain `trace-dep>nested-dep`, not
// the bare `nested-dep`, so the CLI round-trip proves gen-policy emits and enforce matches a
// chain key.
exports.readNested = () => require("nested-dep").readOwn();

// A DIRECT `Module.prototype._compile` under another package's filename — the `compile`
// capability (#93). This is the shape a `require.extensions` transform tool has, and the point
// of the round-trip is that observe records it, gen-policy grants it, and enforce then allows
// it: the policy IS the escape hatch. Under a policy that never saw it, this throws.
exports.compileAsNested = () => {
  const Module = require("module");
  const target = path.join(__dirname, "node_modules", "nested-dep", "generated.js");
  const m = new Module(target, module);
  m.filename = target;
  m.paths = module.paths;
  m._compile("module.exports = 'compiled-ok';", target);
  return m.exports;
};
